const EXTRA_KEY="eosdo-lite-extra-v1";
let extra=JSON.parse(localStorage.getItem(EXTRA_KEY)||"null")||{audit:[],orders:[{id:"o1",title:"Ознакомиться с входящим запросом",owner:"Алексей",due:"2026-09-21",status:"На исполнении"}],reserved:[],issued:[],substitutes:[],assistants:[],savedSearches:[]};
function saveExtra(){localStorage.setItem(EXTRA_KEY,JSON.stringify(extra))}
function logAudit(action,obj){extra.audit.unshift({date:new Date().toLocaleString("ru-RU"),user:"Алексей",action,obj});saveExtra();renderExtra()}
function renderExtra(){
let at=$("#auditTable");if(at)at.innerHTML=(extra.audit.length?extra.audit:[{date:"—",user:"—",action:"События появятся после действий в системе",obj:"—"}]).map(x=>`<tr><td>${x.date}</td><td>${x.user}</td><td>${x.action}</td><td>${x.obj}</td></tr>`).join("");
let ol=$("#ordersList");if(ol)ol.innerHTML=extra.orders.map(o=>`<div class="row"><div><strong>${o.title}</strong><span>Исполнитель: ${o.owner} · срок: ${o.due}</span></div><span class="badge approval">${o.status}</span></div>`).join("");
let cl=$("#controlList");if(cl)cl.innerHTML=extra.orders.filter(o=>o.status!=="Исполнено").map(o=>`<div class="row"><div><strong>${o.title}</strong><span>Контрольный срок: ${o.due}</span></div><button data-finish-order="${o.id}">Исполнить</button></div>`).join("")||'<div class="row"><strong>Незавершённых контрольных поручений нет</strong></div>';
let rl=$("#reservedList");if(rl)rl.innerHTML=extra.reserved.map(n=>`<div class="row"><strong>${n}</strong><span class="badge reg">Зарезервирован</span></div>`).join("")||'<div class="row"><strong>Зарезервированных номеров нет</strong></div>';
let il=$("#issuedList");if(il)il.innerHTML=extra.issued.map(x=>`<div class="row"><div><strong>${x.doc}</strong><span>${x.to}</span></div><span>${x.date}</span></div>`).join("")||'<div class="row"><strong>Выданных оригиналов нет</strong></div>';
}
document.addEventListener("click",e=>{let fin=e.target.closest("[data-finish-order]");if(fin){let o=extra.orders.find(x=>x.id===fin.dataset.finishOrder);if(o){o.status="Исполнено";saveExtra();logAudit("Исполнено поручение",o.title);toast("Поручение исполнено")}}});
$("#freeOrder").onclick=()=>{let title=prompt("Текст поручения");if(!title)return;let due=prompt("Срок исполнения, например 25.09.2026","25.09.2026")||"не указан";extra.orders.unshift({id:String(Date.now()),title,owner:"Алексей",due,status:"На исполнении"});saveExtra();logAudit("Создано свободное поручение",title);toast("Поручение создано")};
$("#reserveBtn").onclick=()=>{let n="РЗ-2026-"+String(extra.reserved.length+1).padStart(4,"0");extra.reserved.unshift(n);saveExtra();logAudit("Зарезервирован номер",n);toast("Номер "+n+" зарезервирован")};
const oldMutate=mutate;mutate=function(id,act){let d=docs.find(x=>x.id===id),name=d?d.number:"Документ";oldMutate(id,act);logAudit("Операция: "+act,name)};
renderExtra();

/* EOSDO workflow expansion: approval/sign queues, links, comments, history and type requisites */
function ensureWorkflow(d){
 d.fields=d.fields||{};d.files=d.files||[];d.links=d.links||[];d.comments=d.comments||[];d.history=d.history||[];
 d.approvalQueue=d.approvalQueue||[{name:"Руководитель подразделения",state:"Ожидает"},{name:"Согласующий",state:"Ожидает"}];
 d.signQueue=d.signQueue||[{name:"Подписант",state:"Ожидает"}];
 return d;
}
docs.forEach(ensureWorkflow);save();
function wfLog(d,event){ensureWorkflow(d);d.history.unshift({at:new Date().toLocaleString("ru-RU"),event,user:"Алексей"});save();logAudit(event,d.number||d.title||d.id)}
function wfAction(id,kind){
 let d=ensureWorkflow(docs.find(x=>x.id===id));if(!d)return;
 if(kind==="startApproval"){d.status="На согласовании";d.approvalQueue[0].state="На согласовании";wfLog(d,"Документ направлен на согласование")}
 if(kind==="approveStage"){let q=d.approvalQueue.find(x=>x.state!=="Согласовано");if(q){q.state="Согласовано";let n=d.approvalQueue.find(x=>x.state==="Ожидает");if(n)n.state="На согласовании";else d.status="Согласован";wfLog(d,"Этап согласования завершён")}}
 if(kind==="startSigning"){d.status="На подписании";d.signQueue[0].state="На подписании";wfLog(d,"Документ направлен на подписание")}
 if(kind==="signStage"){let q=d.signQueue.find(x=>x.state!=="Подписано");if(q){q.state="Подписано";d.status="Подписан";wfLog(d,"Документ подписан")}}
 save();render();openDoc(id);
}
function workflowPanel(d){
 ensureWorkflow(d);
 const queue=(title,a)=>`<div class="wf"><h3>${title}</h3>${a.map((x,i)=>`<div class="row"><span>${i+1}. ${x.name}</span><span class="badge">${x.state}</span></div>`).join("")}</div>`;
 return `<div class="wfgrid">${queue("Очередь согласования",d.approvalQueue)}${queue("Очередь подписания",d.signQueue)}</div>
 <div class="actions"><button data-wf="startApproval" data-id="${d.id}">На согласование</button><button data-wf="approveStage" data-id="${d.id}">Согласовать этап</button><button data-wf="startSigning" data-id="${d.id}">На подписание</button><button data-wf="signStage" data-id="${d.id}">Подписать</button></div>
 <div class="wf"><h3>Связанные документы</h3>${d.links.map(x=>`<div class="row"><span>${x}</span></div>`).join("")||"<p>Связей нет</p>"}<button data-add-link="${d.id}">+ Добавить связь</button></div>
 <div class="wf"><h3>Комментарии</h3>${d.comments.map(x=>`<div class="row"><span>${x.text}</span><small>${x.at}</small></div>`).join("")||"<p>Комментариев нет</p>"}<button data-add-comment="${d.id}">+ Добавить комментарий</button></div>
 <div class="wf"><h3>История</h3>${d.history.map(x=>`<div class="row"><span>${x.event}</span><small>${x.at} · ${x.user}</small></div>`).join("")||"<p>История пуста</p>"}</div>`;
}
const baseOpenDoc=openDoc;
openDoc=function(id){baseOpenDoc(id);let d=docs.find(x=>x.id===id);let body=$("#drawerBody");if(d&&body)body.insertAdjacentHTML("beforeend",workflowPanel(d))};
document.addEventListener("click",e=>{
 let w=e.target.closest("[data-wf]");if(w){wfAction(w.dataset.id,w.dataset.wf);return}
 let l=e.target.closest("[data-add-link]");if(l){let d=ensureWorkflow(docs.find(x=>x.id===l.dataset.addLink));let v=prompt("Номер или название связанного документа");if(v){d.links.push(v);wfLog(d,"Добавлен связанный документ: "+v);openDoc(d.id)}return}
 let m=e.target.closest("[data-add-comment]");if(m){let d=ensureWorkflow(docs.find(x=>x.id===m.dataset.addComment));let v=prompt("Комментарий");if(v){d.comments.unshift({text:v,at:new Date().toLocaleString("ru-RU")});wfLog(d,"Добавлен комментарий");openDoc(d.id)}}
});

/* EOSDO persistence: requisites, attachments metadata and registration stage */
function collectTypeFields(form,type){let out={};(typeFieldMap[type]||[]).forEach(([label,name])=>{let el=form.elements[name];if(el&&el.value)out[name]={label,value:el.value}});return out}
function renderRequisites(d){ensureWorkflow(d);let vals=Object.values(d.fields||{});return vals.length?`<div class="wf"><h3>Дополнительные реквизиты</h3>${vals.map(x=>`<div class="row"><span>${x.label}</span><strong>${x.value}</strong></div>`).join("")}</div>`:""}
function renderFiles(d){ensureWorkflow(d);return `<div class="wf"><h3>Файлы</h3>${d.files.length?d.files.map(x=>`<div class="row"><span>${x.name}</span><small>${Math.max(1,Math.round(x.size/1024))} КБ · ${x.type||"файл"}</small></div>`).join(""):"<p>Файлы не добавлены</p>"}<button data-add-file="${d.id}">+ Добавить файл</button></div>`}
const wfOpenDoc=openDoc;
openDoc=function(id){wfOpenDoc(id);let d=docs.find(x=>x.id===id),body=$("#drawerBody");if(d&&body)body.insertAdjacentHTML("beforeend",renderRequisites(d)+renderFiles(d)+`<div class="actions"><button data-register="${d.id}">Зарегистрировать</button></div>`)}
document.addEventListener("click",e=>{let r=e.target.closest("[data-register]");if(r){let d=ensureWorkflow(docs.find(x=>x.id===r.dataset.register));if(d){d.status="Зарегистрирован";d.registration={number:d.number,date:new Date().toLocaleDateString("ru-RU"),registrar:"Алексей"};wfLog(d,"Документ зарегистрирован");render();openDoc(d.id);toast("Документ зарегистрирован")}}let af=e.target.closest("[data-add-file]");if(af){let inp=document.createElement("input");inp.type="file";inp.multiple=true;inp.onchange=()=>{let d=ensureWorkflow(docs.find(x=>x.id===af.dataset.addFile));[...inp.files].forEach(x=>d.files.push({name:x.name,size:x.size,type:x.type,lastModified:x.lastModified}));wfLog(d,"Добавлены файлы: "+[...inp.files].map(x=>x.name).join(", "));openDoc(d.id)};inp.click()}})
const originalCreate=$("#createForm").onsubmit;
$("#createForm").onsubmit=e=>{e.preventDefault();let form=e.target,f=new FormData(form),type=f.get("type"),prefix=type==="Договор"?"ДГ":type.includes("довер")?"ЗД":type==="Входящий документ"?"ВХ":type==="Исходящий документ"?"ИСХ":"ПР",files=[...(form.elements.files?.files||[])].map(x=>({name:x.name,size:x.size,type:x.type,lastModified:x.lastModified}));let d=ensureWorkflow({id:String(Date.now()),number:`${prefix}-2026-${String(docs.length+101).padStart(4,"0")}`,title:f.get("title"),type,status:"На согласовании",owner:f.get("owner"),urgency:f.get("urgency"),access:f.get("access"),comment:f.get("comment"),fields:collectTypeFields(form,type),files,route:["Создание проекта — завершено","Согласование — текущий этап"]});d.history.unshift({at:new Date().toLocaleString("ru-RU"),event:"Создан проект документа",user:"Алексей"});docs.unshift(d);save();logAudit("Создан проект документа",d.number);form.reset();renderTypeFields();$("#createDlg").close();show("docs");render();toast("Проект документа создан")}
